import{_ as e,o as a,c as n,am as o}from"./chunks/framework.yj4qiWdr.js";const s="/skill-issue/assets/save-progress-in-exam.C4_r1Zma.png",m=JSON.parse('{"title":"Exam Instructions","description":"","frontmatter":{},"headers":[],"relativePath":"crto/botesjuan/notes/Exam-Instructions.md","filePath":"crto/botesjuan/notes/Exam-Instructions.md"}'),i={name:"crto/botesjuan/notes/Exam-Instructions.md"};function r(l,t,d,c,h,u){return a(),n("div",null,t[0]||(t[0]=[o('<h1 id="exam-instructions" tabindex="-1">Exam Instructions <a class="header-anchor" href="#exam-instructions" aria-label="Permalink to &quot;Exam Instructions&quot;">​</a></h1><h2 id="launching-the-exam" tabindex="-1">Launching the Exam <a class="header-anchor" href="#launching-the-exam" aria-label="Permalink to &quot;Launching the Exam&quot;">​</a></h2><p>Click <strong>Red Team Operator Exam</strong> lesson in the course menu.</p><blockquote><p>Do NOT navigate away from the exam page while it is running. Open course material in a separate tab/window.</p></blockquote><p>The lab ID number is shown at the bottom of the instructions panel — include it in any support contact.</p><hr><h2 id="exam-scenario" tabindex="-1">Exam Scenario <a class="header-anchor" href="#exam-scenario" aria-label="Permalink to &quot;Exam Scenario&quot;">​</a></h2><ul><li><strong>Assume-breach</strong> scenario — no pre-running Beacon, but access to a foothold machine on the internal network.</li><li>You must deploy a Beacon manually. <strong>This may require bypassing host-based defences first.</strong></li><li>The instruction panel presents the <strong>operational objective</strong> and <strong>rules of engagement</strong> (off-limit hosts, restrictions).</li></ul><hr><h2 id="scoring" tabindex="-1">Scoring <a class="header-anchor" href="#scoring" aria-label="Permalink to &quot;Scoring&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Component</th><th>Points</th></tr></thead><tbody><tr><td>Operational objective</td><td>50 pts</td></tr><tr><td>OPSEC discipline</td><td>50 pts</td></tr><tr><td><strong>Minimum to pass</strong></td><td><strong>85 pts</strong></td></tr></tbody></table><blockquote><p><strong>Achieving the objective alone is not enough to pass. You need both.</strong><strong>You will fail if OPSEC score drops too low, even if the objective is complete.</strong></p></blockquote><hr><h2 id="opsec-scoring-criteria-—-know-these-cold" tabindex="-1">OPSEC Scoring Criteria — Know These Cold <a class="header-anchor" href="#opsec-scoring-criteria-—-know-these-cold" aria-label="Permalink to &quot;OPSEC Scoring Criteria — Know These Cold&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Criterion</th><th>What Triggers a Deduction</th><th>Mitigation</th></tr></thead><tbody><tr><td><strong>Blocked by Defender / AppLocker</strong></td><td>AV blocking payload execution at any stage</td><td>Artifact Kit + Resource Kit clean before exam start</td></tr><tr><td><strong>Outbound from unusual processes</strong></td><td>Beacon HTTP callback from a process that doesn&#39;t legitimately make web requests</td><td>Run Beacon inside browser, svchost, dllhost — set <code>spawnto</code> and <code>ppid</code></td></tr><tr><td><strong>Default CS indicators</strong></td><td>Default named pipe names, default injection technique</td><td>Customise <code>post-ex.pipename</code> and <code>process-inject</code> block in Malleable C2 profile</td></tr><tr><td><strong>Suspicious lateral movement</strong></td><td><code>jump psexec</code> / service creation event logs</td><td>Prefer <code>jump winrm64</code> → <code>remote-exec wmi</code> → psexec only as last resort</td></tr><tr><td><strong>Suspicious LSASS handles</strong></td><td>Direct LSASS handle from non-system process</td><td>Use <code>nanodump</code> BOF — never Mimikatz direct against LSASS</td></tr><tr><td><strong>Disabling security controls</strong></td><td>Turning off Defender or Windows Firewall</td><td><strong>Never disable Defender or Firewall — automatic deduction</strong></td></tr></tbody></table><hr><h2 id="off-limit-hosts-—-instant-fail" tabindex="-1">Off-Limit Hosts — Instant Fail <a class="header-anchor" href="#off-limit-hosts-—-instant-fail" aria-label="Permalink to &quot;Off-Limit Hosts — Instant Fail&quot;">​</a></h2><blockquote><p><em>&quot;You will fail the exam if you generate an alert on an off-limit host, even if you achieve the operational objective.&quot;</em></p></blockquote><p><strong>Read the rules of engagement before touching anything.</strong> Enumerate scope before any lateral move. Do not assume all visible hosts are in scope.</p><hr><h2 id="time-limits" tabindex="-1">Time Limits <a class="header-anchor" href="#time-limits" aria-label="Permalink to &quot;Time Limits&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Limit</th><th>Value</th></tr></thead><tbody><tr><td>Lab runtime</td><td>24 hours total (across all sessions)</td></tr><tr><td>Calendar window</td><td>7 days to complete and submit</td></tr><tr><td>Cooldown between attempts</td><td>7 days</td></tr><tr><td>Active time before Save becomes available</td><td>15–20 minutes</td></tr></tbody></table><hr><h2 id="saving-progress-—-critical-ui-distinction" tabindex="-1">Saving Progress — Critical UI Distinction <a class="header-anchor" href="#saving-progress-—-critical-ui-distinction" aria-label="Permalink to &quot;Saving Progress — Critical UI Distinction&quot;">​</a></h2><img src="'+s+`" width="860"><table tabindex="0"><thead><tr><th>Button</th><th>Result</th></tr></thead><tbody><tr><td><strong>Exit Lab → Save Progress And Exit</strong></td><td>VMs saved, environment paused — <strong>safe</strong></td></tr><tr><td><strong>Exit Lab → End Lab</strong></td><td><strong>Instant, permanent, irreversible destruction of exam attempt</strong></td></tr></tbody></table><blockquote><p><strong>You must be active in the environment for 15–20 minutes before Save Progress And Exit becomes available.</strong> Do not launch unless you are ready to work immediately — launching and immediately closing terminates the environment and still counts as an attempt.</p></blockquote><hr><h2 id="persistence-is-required-—-do-not-rely-on-save-progress" tabindex="-1">Persistence is Required — Do Not Rely on Save Progress <a class="header-anchor" href="#persistence-is-required-—-do-not-rely-on-save-progress" aria-label="Permalink to &quot;Persistence is Required — Do Not Rely on Save Progress&quot;">​</a></h2><blockquote><p><em>&quot;You should not rely on this feature to preserve your running Beacons, particularly those in a P2P chain. Make sure you have proper persistence setup as you would in the real world.&quot;</em></p></blockquote><p>When you resume after saving, any SMB/P2P Beacon chain will be dead. Persistence must survive reboot. Set persistence <strong>before</strong> taking a break.</p><hr><h2 id="submission-and-grading" tabindex="-1">Submission and Grading <a class="header-anchor" href="#submission-and-grading" aria-label="Permalink to &quot;Submission and Grading&quot;">​</a></h2><ul><li>Click <strong>Submit</strong> at the bottom of the instructions panel to end the exam for grading.</li><li><strong>Submit is permanent</strong> — do not click accidentally.</li><li>Do not navigate away or close the page while grading is in progress (takes several minutes).</li><li>After grading, click <strong>&quot;Update &amp; Close&quot;</strong> to post your score to the course platform — <strong>failure to do this means you cannot claim the certification.</strong></li></ul><hr><h2 id="pre-exam-checklist" tabindex="-1">Pre-Exam Checklist <a class="header-anchor" href="#pre-exam-checklist" aria-label="Permalink to &quot;Pre-Exam Checklist&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>[ ] Read rules of engagement — identify off-limit hosts before touching anything</span></span>
<span class="line"><span>[ ] SSH to team server → update Malleable C2 profile (stage, post-ex, process-inject)</span></span>
<span class="line"><span>[ ] Patch Artifact Kit (patch.c) → build → ThreatCheck clean</span></span>
<span class="line"><span>[ ] Build Resource Kit → fix template.x64.ps1 → ThreatCheck AMSI clean</span></span>
<span class="line"><span>[ ] Load artifact.cna + resources.cna in CS Script Manager</span></span>
<span class="line"><span>[ ] Test beacon callback with Defender ON before engaging targets</span></span>
<span class="line"><span>[ ] Set spawnto away from default rundll32.exe</span></span>
<span class="line"><span>[ ] Set custom named pipe pattern in post-ex.pipename</span></span>
<span class="line"><span>[ ] Have persistence technique ready to deploy after first beacon checks in</span></span></code></pre></div>`,37)]))}const g=e(i,[["render",r]]);export{m as __pageData,g as default};
